#nullable enable
using Alba;
using HourBooking.Contracts;
using HourBooking.Slices.Booking;
using Shouldly;
using Xunit;

namespace HourBooking.IntegrationTests.Slices.Booking;

/// <summary>
/// Generated from the model's GWT cells, NOT from the implementation. Pattern: command.
/// Status: in-progress. LIVE: this slice is claimed, so every test here must pass.
///
/// Second slice on the Timesheet stream, so the GIVENs append HoursBooked directly — history, not a
/// sequence of requests to replay. correct-hours has no membership rule: the rule that refuses a
/// project is on booking, and a correction names a booking that already exists.
/// </summary>
public sealed class CorrectHoursTests(AppFixture fixture) : IntegrationContext(fixture)
{
    private static string Timesheet => CorrectHoursState.StreamKey(SeedData.EmployeeId, SeedData.Month);
    private static string MonthClosure => MonthGate.StreamKey(SeedData.EmployeeId, SeedData.Month);

    private static BookingMonthStarted MonthOpened =>
        new(SeedData.EmployeeId, SeedData.EmployeeName, SeedData.Month, SeedData.SeededAt);

    private static readonly Guid Booking = Guid.Parse("bbbb0000-0000-0000-0000-00000000000b");

    private static HoursBooked Booked(decimal hours, Guid? id = null, Guid? projectId = null) =>
        new(id ?? Booking, SeedData.EmployeeId, SeedData.Month, projectId ?? SeedData.ProjectId,
            SeedData.WorkingDay, hours, "as booked", SeedData.SeededAt);

    private async Task<IScenarioResult> Correct(decimal hours, Guid? bookingId = null, string? note = null)
    {
        var id = bookingId ?? Booking;
        var (_, result) = await WhenPosting(x =>
        {
            x.Post
                .Json(new CorrectHours(id, SeedData.EmployeeId, SeedData.Month, hours, note))
                .ToUrl($"/timesheet/{SeedData.EmployeeId}/{SeedData.Month}/bookings/{id}/corrections");
            x.IgnoreStatusCode();
        });
        return result;
    }

    // a correction carries the new TOTAL for the day, never the difference
    //   GIVEN HoursBooked  WHEN CorrectHours  THEN HoursCorrected
    [Fact]
    public async Task ACorrectionCarriesTheNewTOTALForTheDayNeverTheDifference()
    {
        await Given(MonthClosure, MonthOpened);
        await Given(Timesheet, Booked(6m));

        var result = await Correct(8m);

        result.Context.Response.StatusCode.ShouldBe(204);
        var corrected = (await EventsFor(Timesheet)).OfType<HoursCorrected>().ShouldHaveSingleItem();
        corrected.Hours.ShouldBe(8m);          // the new total, not the 2 difference
        corrected.BookingId.ShouldBe(Booking);
        corrected.Month.ShouldBe(SeedData.Month);
    }

    // the truth for a day+project is the last correction, or the booking if there was none
    //   GIVEN HoursBooked, HoursCorrected  THEN HoursCorrected
    [Fact]
    public async Task TheTruthForADayProjectIsTheLastCorrectionOrThe()
    {
        await Given(MonthClosure, MonthOpened);
        await Given(Timesheet,
            Booked(6m),
            new HoursCorrected(Booking, SeedData.EmployeeId, SeedData.Month, 8m, null, SeedData.SeededAt));

        var result = await Correct(9m);

        result.Context.Response.StatusCode.ShouldBe(204);
        var corrections = (await EventsFor(Timesheet)).OfType<HoursCorrected>().ToArray();
        corrections.Length.ShouldBe(2);
        corrections.Last().Hours.ShouldBe(9m);   // last correction wins

        // And the read model agrees, because the projection is inline.
        var sheet = await Host.Scenario(x =>
            x.Get.Url($"/timesheet/{SeedData.EmployeeId}/{SeedData.Month}"));
        (await sheet.ReadAsTextAsync()).ShouldContain("\"hours\": 9");
    }

    // correcting a day+project that was never booked is not a correction
    //   GIVEN BookingMonthStarted  THEN error: BookingNotFound
    [Fact]
    public async Task CorrectingADayProjectThatWasNeverBookedIsNotACorrection()
    {
        await Given(MonthClosure, MonthOpened);
        // No HoursBooked at all: the month is open and empty.

        var result = await Correct(8m);

        result.Context.Response.StatusCode.ShouldBe(400);
        (await EventsFor(Timesheet)).ShouldBeEmpty();
    }

    // a correction cannot take the hours to zero — removal is the only way
    //   THEN error: HoursMustBeNonZero      enforce="periphery"
    [Fact]
    public async Task ACorrectionCannotTakeTheHoursToZeroRemovalIsTheOnly()
    {
        await Given(MonthClosure, MonthOpened);
        await Given(Timesheet, Booked(6m));

        var result = await Correct(0m);

        result.Context.Response.StatusCode.ShouldBe(400);
        (await EventsFor(Timesheet)).OfType<HoursCorrected>().ShouldBeEmpty();
    }

    // corrections are in whole or half hours only
    //   THEN error: HoursMustBeWholeOrHalf   enforce="periphery"
    [Fact]
    public async Task CorrectionsAreInWholeOrHalfHoursOnly()
    {
        await Given(MonthClosure, MonthOpened);
        await Given(Timesheet, Booked(6m));

        var result = await Correct(7.25m);

        result.Context.Response.StatusCode.ShouldBe(400);
        (await EventsFor(Timesheet)).OfType<HoursCorrected>().ShouldBeEmpty();
    }

    // a correction cannot push the day over 18 hours
    //   THEN error: DailyCapExceeded
    [Fact]
    public async Task ACorrectionCannotPushTheDayOver18Hours()
    {
        var other = Guid.Parse("cccc0000-0000-0000-0000-00000000000c");
        await Given(MonthClosure, MonthOpened);
        await Given(Timesheet,
            Booked(6m),
            // A second booking on the SAME day, so 12 hours stand beside the one being corrected.
            Booked(12m, id: other, projectId: SeedData.LeftProjectId));

        // 12 elsewhere + 7 asked for = 19, over the cap. The 6 being REPLACED must not be counted.
        var result = await Correct(7m);

        result.Context.Response.StatusCode.ShouldBe(400);
        (await EventsFor(Timesheet)).OfType<HoursCorrected>().ShouldBeEmpty();

        // The boundary the other way: 12 + 6 = 18 is exactly the cap and must be allowed. This is what
        // proves the correction's own hours were excluded, rather than the check merely being loose.
        (await Correct(6m)).Context.Response.StatusCode.ShouldBe(204);
    }

    // a closed month cannot be corrected — closed is closed
    //   GIVEN MonthClosed  THEN error: MonthIsClosed
    [Fact]
    public async Task AClosedMonthCannotBeCorrectedClosedIsClosed()
    {
        await Given(MonthClosure, MonthOpened,
            new MonthClosed(SeedData.EmployeeId, SeedData.Month, SeedData.AdminId, null, SeedData.SeededAt));
        await Given(Timesheet, Booked(6m));

        var result = await Correct(8m);

        result.Context.Response.StatusCode.ShouldBe(400);
        (await EventsFor(Timesheet)).OfType<HoursCorrected>().ShouldBeEmpty();
    }

    // a submitted month is still open, so it can still be corrected
    //   GIVEN MonthClosureSubmitted  THEN HoursCorrected
    [Fact]
    public async Task ASubmittedMonthIsStillOpenSoItCanStillBeCorrected()
    {
        await Given(MonthClosure, MonthOpened,
            new MonthClosureSubmitted(SeedData.EmployeeId, SeedData.Month, SeedData.SeededAt));
        await Given(Timesheet, Booked(6m));

        var result = await Correct(8m);

        result.Context.Response.StatusCode.ShouldBe(204);
        (await EventsFor(Timesheet)).OfType<HoursCorrected>().ShouldHaveSingleItem().Hours.ShouldBe(8m);
    }
}
